<?php
$gbp=0;$count=0;foreach(wc_get_products(['limit'=>-1,'status'=>'publish']) as $p){$count++;try{if(Instapass_Control_GBP::effective((string)$p->get_meta('_instapass_gbp_regular_price'),(string)$p->get_meta('_instapass_gbp_sale_price'))!==null)$gbp++;}catch(InvalidArgumentException $e){}}
$resp=wp_remote_get('https://api.country.is/81.2.69.142',['timeout'=>5,'redirection'=>0]);$geo=is_wp_error($resp)?'unavailable':json_decode(wp_remote_retrieve_body($resp),true)['country']??'unknown';
echo wp_json_encode(['version'=>INSTAPASS_CONTROL_VERSION,'effective_pkr_rate'=>instapass_control_rate(),'stored_pkr_rate'=>get_option('instapass_pkr_rate'),'published_products'=>$count,'products_with_gbp_price'=>$gbp,'orders'=>wc_get_orders(['limit'=>1,'paginate'=>true])->total,'uk_sample_ip_country'=>$geo,'geolocation_source'=>'server-side HTTPS country.is with unknown fallback to USD','base_currency'=>get_option('woocommerce_currency'),'checkout_url'=>wc_get_checkout_url(),'shop_url'=>wc_get_page_permalink('shop')],JSON_PRETTY_PRINT);
